// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, type(uint128).max);
        vm.deal(caller, amount);
        uint256 oldBalance = c.getBalance(caller);
        vm.prank(caller);
        c.addToBalance{value: amount}();
        uint256 newBalance = c.getBalance(caller);
        assertTrue(newBalance == oldBalance + amount);
    }
}
